/// The engine's settings (core/knobs.def) by name, so the app cannot misspell one.
enum EngineKnob: String, CaseIterable {
    /// Blocks continue past direct branches into one longer translation.
    case superblocks = "HV_SUPERBLOCKS"
    /// Neighbouring memory accesses checked as one group.
    case groups = "HV_GROUPS"
    /// Every return goes through the indirect-branch cache (no return prediction).
    case noRas = "HV_NO_RAS"
    /// Testing: each block in one part (hot and cold code together).
    case k2 = "HV_K2"
    /// Testing: every guest register spilled around helper calls.
    case k3 = "HV_K3"
    /// TLB laid out table-major (0: entry-major).
    case tlbt = "HV_TLBT"
    /// Testing: MB of the code region used from the start (0: all of it).
    case jitCap = "HV_JIT_CAP"
    /// Exact check for accesses in a page's last 15 bytes in their out-of-line path.
    case recheck = "HV_RECHECK"
    /// A CPU waiting for TLB acknowledgements sleeps after 64 spins.
    case syncWait = "HV_SYNC_WAIT"
    /// Skip the local TLB flush xnu issues after a process switch (1-3: ways of checking it).
    case switchFlush = "HV_SWITCH_FLUSH"
    /// TLB range invalidations of up to this many pages in one pass (0: off).
    case rangeDrop = "HV_RANGE_DROP"
    /// Constants built in registers instead of loaded from the literal pool.
    case movimm = "HV_MOVIMM"
    /// Measuring: every access through the C helper, with prediction statistics.
    case predstat = "HV_PREDSTAT"
    /// Remote TLB drops skip CPUs whose page walks did not touch the page.
    case walkLog = "HV_WALK_LOG"
    /// The exit check of backward branches hoisted out of loops.
    case hoistCheck = "HV_HOIST_CHECK"
    /// A code change drops only that page's branch-cache targets.
    case ijcPages = "HV_IJC_PAGES"
    /// The guest's DNS through the host's resolver.
    case dnsProxy = "HV_DNS_PROXY"
    /// Microseconds an idle CPU watches for work before sleeping.
    case wfiSpin = "HV_WFI_SPIN"
    /// Disk flush: 0 fsync, 1 none, 2 F_BARRIERFSYNC.
    case flush = "HV_FLUSH"
    /// Every exception entry and return through the dispatcher.
    case noFastResume = "HV_NO_FAST_RESUME"
    /// A WFE always leaves for the dispatcher instead of waiting in place.
    case wfeSpin = "HV_WFE_SPIN"
    /// A process switch drops the user TLB entries instead of stashing them.
    case noStash = "HV_NO_STASH"
    /// IC IVAU drops the page's translations (as before they were kept).
    case icIvau = "HV_IC_IVAU"
    /// IC IALLU drops every translation (as before they were kept).
    case icFlush = "HV_IC_FLUSH"
    /// Debugging: every chained exit checks for an exit request.
    case exitChecks = "HV_EXIT_CHECKS"
    /// Branches to another page never chain.
    case noXchain = "HV_NO_XCHAIN"
    /// Each branch to another page does its own cache lookup instead of the shared thunk.
    case inlineXjump = "HV_INLINE_XJUMP"
    /// Debugging: every exclusive access through the C helper.
    case cExcl = "HV_C_EXCL"
    /// Every TLBI ends its block, as before.
    case tlbiLeaves = "HV_TLBI_LEAVES"
    /// Debugging: every load and store through the C helper.
    case slowMem = "HV_SLOW_MEM"
    /// Debugging: one CPU in guest code at a time.
    case bigLock = "HV_BIG_LOCK"
    /// Debugging: freed code poisoned, and each block's flush generation checked as it runs.
    case jitPoison = "HV_JIT_POISON"
    /// Debugging: which code pages changed since they were translated.
    case codeCheck = "HV_CODE_CHECK"
    /// Debugging: what came before branch-cache misses that were cached.
    case ijcDebug = "HV_IJC_DEBUG"
    /// Debugging: every PSCI call.
    case psciLog = "HV_PSCI_LOG"
    /// Measuring: a file for sampled translated blocks (guest and host words, for bench/hvdis.py).
    case blockDump = "HV_BLOCK_DUMP"
    /// Measuring: HV_BLOCK_DUMP keeps every Nth block.
    case blockDumpEvery = "HV_BLOCK_DUMP_EVERY"
    /// Measuring: the function the profiler shows per offset.
    case profFn = "HV_PROF_FN"
    /// Measuring: which kernel VAs get TLB fills, per bucket.
    case kvaHist = "HV_KVA_HIST"
    /// Measuring: where HV_KVA_HIST's buckets start.
    case kvaBase = "HV_KVA_BASE"
    /// Measuring: log2 of the bytes in each HV_KVA_HIST bucket.
    case kvaShift = "HV_KVA_SHIFT"
    /// Seconds between engine stats lines in the log (0: none).
    case stats = "HV_STATS"
