    case statsDeep = "HV_STATS_DEEP"
    /// The refresh rate macOS is told its display has.
    case hz = "HV_HZ"
    /// Frames a second shown while saving power (hot device); 0: every frame.
    case savingHz = "HV_SAVING_HZ"
