    case pvgPlanarCopy = "HV_PVG_PLANAR_COPY"
    /// Multi-plane surfaces read from plane 0 only.
    case pvgPlane0 = "HV_PVG_PLANE0"
    /// Debugging: the first N render pass records, raw and as read.
    case pvgPassdump = "HV_PVG_PASSDUMP"
    /// Debugging: each GPU command buffer waited for.
    case pvgSync = "HV_PVG_SYNC"
    /// Debugging: pointer glyphs and visibility.
